 IF;:NEW.VERSION := OVERSION;END IF; IF INSERTING THEN DELETE FROM
 PS_ZZ_PCODE_LAB_TX WHERE  :NEW.ZZ_PCODE_LAB_KEY =
 PS_ZZ_PCODE_LAB_TX.ZZ_PCODE_LAB_KEY;  UPDATE PSOPTSYNC SET VERSION =
 VERSION + 1  WHERE PSOPTSYNC.PROBINST = '$ALL$' AND PSOPTSYNC.RECNAME
 = 'ZZ_PCODE_LAB_R1' ;SELECT VERSION INTO OVERSION FROM PSOPTSYNC 
 WHERE PSOPTSYNC.PROBINST = '$ALL$' AND PSOPTSYNC.RECNAME =
 'ZZ_PCODE_LAB_R1' ;:NEW.VERSION := OVERSION;END IF; IF DELETING THEN 
 UPDATE PSOPTSYNC SET VERSION = VERSION + 1  WHERE PSOPTSYNC.PROBINST
 = '$ALL$' AND PSOPTSYNC.RECNAME = 'ZZ_PCODE_LAB_R1' ;SELECT VERSION
